using sv_c8544cc8613a45d79f3ba2781c1268ca.Models;

namespace sv_c8544cc8613a45d79f3ba2781c1268ca.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella and basil.", 25),
            new(2, "Spaghetti Carbonara", "Creamy pasta with pancetta, egg, and pecorino romano.", 20),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 40),
            new(4, "Risotto ai Funghi", "Creamy Arborio rice with porcini mushrooms and Parmesan.", 35),
        },
        [2] = new List<Recipe>
        {
            new(5, "Chicken Tikka Masala", "Tender chicken in a creamy spiced tomato sauce.", 45),
            new(6, "Palak Paneer", "Spinach curry with cubes of fresh paneer cheese.", 30),
            new(7, "Biryani", "Fragrant basmati rice layered with spiced meat and saffron.", 60),
            new(8, "Samosa", "Crispy pastry filled with spiced potatoes and peas.", 50),
        },
        [3] = new List<Recipe>
        {
            new(9, "Sushi Roll", "Fresh fish and vegetables wrapped in seasoned rice and nori.", 45),
            new(10, "Ramen", "Rich pork broth with noodles, soft egg, and chashu.", 90),
            new(11, "Tempura", "Lightly battered and fried shrimp and vegetables.", 25),
            new(12, "Miso Soup", "Warm dashi broth with tofu, seaweed, and green onion.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_c8544cc8613a45d79f3ba2781c1268ca.Models
@using sv_c8544cc8613a45d79f3ba2781c1268ca.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <h3>Recipes for Cuisine @CuisineId</h3>
    @if (_recipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <ul>
            @foreach (var recipe in DisplayRecipes)
            {
                <li>
                    <strong>@recipe.Title</strong> — @recipe.Description
                    <br /><small>Prep time: @recipe.PrepTimeMinutes min</small>
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    private IReadOnlyList<Recipe> DisplayRecipes =>
        Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes!.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes!.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes!,
        };

    protected override async Task OnParametersSetAsync()
    {
        // Only reload data when the cuisine changes, not when sort changes.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingRequestAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        _loadedCuisineId = CuisineId;

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale response if cancellation raced.
            if (!cts.Token.IsCancellationRequested)
            {
                _recipes = result;
                _isRefreshing = false;
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when user navigates away or switches cuisine. Do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

